import math

def check_n_good(g, n, a, b):
    """Checks if g(a) - g(b) divides a^n - b^n."""
    if a == b:
        return True

    numerator = a**n - b**n
    denominator = g(a) - g(b)

    if denominator == 0:
        # Since a != b and n >= 1, numerator cannot be 0. 
        # Division by zero means the condition fails unless we handle 0|X=0 case.
        # As established, g must be injective, so denominator != 0.
        return False 

    return numerator % denominator == 0

# Test function g(x) = x^k
