def tau(n):
    """Calculates the number of divisors of n."""
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic(n):
    if n == 1:
        # We confirmed C_1 = 2, so 1 is exotic (2 = 2 * 1)
        return True

    tau_n = tau(n)
    # Check if tau_n = 2 * odd_integer
    if tau_n % 2 != 0:
        return False # Must be even

    odd_factor = tau_n // 2
    return odd_factor % 2 != 0

# Since the 132nd prime is 743, we start checking far above 1.
